"""TCP and UDP echo endpoint for the Android Traffic Test app."""

import argparse
import asyncio
import re


def report(protocol, peer, payload, size):
    # Print only the identifier generated by the app, never arbitrary payloads.
    probe = re.fullmatch(rb"traffic-test/([0-9a-f]{8})", payload)
    token = probe[1].decode("ascii") if probe else "-"
    print(f"{protocol} {peer} {size} bytes id={token}", flush=True)


async def echo_tcp(reader, writer):
    peer = writer.get_extra_info("peername")
    sample = bytearray()
    total = 0
    try:
        while data := await asyncio.wait_for(reader.read(8192), timeout=10):
            writer.write(data)
            await writer.drain()
            # TCP can deliver the probe in multiple reads.
            total += len(data)
            sample.extend(data[: 22 - len(sample)])
    except (asyncio.TimeoutError, ConnectionError):
        pass
    finally:
        writer.close()
        report("TCP", peer, sample, total)


class UdpEcho(asyncio.DatagramProtocol):
    def connection_made(self, transport):
        self.transport = transport

    def datagram_received(self, data, peer):
        self.transport.sendto(data, peer)
        report("UDP", peer, data, len(data))


async def serve(bind, port):
    async with await asyncio.start_server(echo_tcp, bind, port) as server:
        udp, _ = await asyncio.get_running_loop().create_datagram_endpoint(
            UdpEcho, local_addr=(bind, port)
        )
        try:
            print(f"Listening on {bind}:{port} (TCP and UDP)", flush=True)
            await server.serve_forever()
        finally:
            udp.close()


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--bind", default="127.0.0.1")
    parser.add_argument("--port", type=int, choices=range(1, 65536), metavar="PORT", default=39007)
    args = parser.parse_args()
    try:
        asyncio.run(serve(args.bind, args.port))
    except KeyboardInterrupt:
        pass
